let obstacles = [
    { x: 100, y: 100, radius: 15, dx: 2, dy: 0 },
    { x: 200, y: 200, radius: 15, dx: -2, dy: 0 },
    { x: 300, y: 300, radius: 15, dx: 0, dy: 2 }
];

function update() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Move player
    player.x += player.dx;
    player.y += player.dy;

    // Move obstacles
    for (let obstacle of obstacles) {
        obstacle.x += obstacle.dx;
        obstacle.y += obstacle.dy;

        // Bounce obstacles off walls
        if (obstacle.x + obstacle.radius > canvas.width || obstacle.x - obstacle.radius < 0) {
            obstacle.dx = -obstacle.dx;
        }
        if (obstacle.y + obstacle.radius > canvas.height || obstacle.y - obstacle.radius < 0) {
            obstacle.dy = -obstacle.dy;
        }
    }

    // Check for collisions
    checkCollisions();

    // Draw player
    ctx.beginPath();
    ctx.arc(player.x, player.y, player.radius, 0, Math.PI * 2);
    ctx.fillStyle = 'blue';
    ctx.fill();
    ctx.closePath();

    // Draw obstacles
    for (let obstacle of obstacles) {
        ctx.beginPath();
        ctx.arc(obstacle.x, obstacle.y, obstacle.radius, 0, Math.PI * 2);
        ctx.fillStyle = 'red';
        ctx.fill();
        ctx.closePath();
    }

    requestAnimationFrame(update);
}

function checkCollisions() {
    for (let obstacle of obstacles) {
        let dx = player.x - obstacle.x;
        let dy = player.y - obstacle.y;
        let distance = Math.sqrt(dx * dx + dy * dy);
        if (distance < player.radius + obstacle.radius) {
            gameOver();
            break;
        }
    }
}

function gameOver() {
    ctx.fillStyle = 'red';
    ctx.font = '48px Arial';
    ctx.textAlign = 'center';
    ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
    player.dx = 0;
    player.dy = 0;
    obstacles.forEach(obstacle => {
        obstacle.dx = 0;
        obstacle.dy = 0;
    });
}

update();

